def find_starting_indices(words, s, l):
    """
    Returns the starting indices in the string s where the substrings of length l are valid words from the list words.
    """
    word_set = set(words)
    indices = []
    for i in range(0, len(s) - l + 1):
        if s[i:i+l] in word_set:
            indices.append(i)
    return indices

import heapq

def trap_rain_water(height_map):
    if not height_map or not height_map[0]:
        return 0

    m, n = len(height_map), len(height_map[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Push all the border cells into the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m-1 or j == 0 or j == n-1:
                heapq.heappush(heap, (height_map[i][j], i, j))
                visited[i][j] = True

    water_trapped = 0
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                trapped = max(0, height - height_map[nx][ny])
                water_trapped += trapped
                visited[nx][ny] = True
                heapq.heappush(heap, (max(height, height_map[nx][ny]), nx, ny))

    return water_trapped

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than n using the Sieve of Eratosthenes algorithm.
    """
    if n <= 2:
        return []

    primes = [True] * n
    primes[0] = primes[1] = False

    for start in range(2, int(n ** 0.5) + 1):
        if primes[start]:
            for multiple in range(start*start, n, start):
                primes[multiple] = False

    return [num for num, is_prime in enumerate(primes) if is_prime]

import math

def smallest_positive_multiple(a, b):
    """
    Returns the smallest positive integer that is a multiple of both a and b.
    If a or b is non-positive, returns -1.
    """
    if a <= 0 or b <= 0:
        return -1
    return abs(a * b) // math.gcd(a, b)

